class MultiScaleBlock(nn.Module):

    def __init__(self, channels: int) -> None:
        super().__init__()
        branch_channels = channels // 2
        self.local = nn.Sequential(nn.Conv2d(channels, branch_channels, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(branch_channels), nn.GELU())
        self.context = nn.Sequential(nn.Conv2d(channels, branch_channels, kernel_size=3, padding=2, dilation=2, bias=False), nn.BatchNorm2d(branch_channels), nn.GELU())
        self.fuse = nn.Sequential(nn.Conv2d(channels, channels, kernel_size=1, bias=False), nn.BatchNorm2d(channels))

    def forward(self, features: torch.Tensor) -> torch.Tensor:
        mixed = torch.cat((self.local(features), self.context(features)), dim=1)
        return F.gelu(features + self.fuse(mixed))

